CREATE TABLE public.cig_settings (id int primary key default 1 check (id = 1), base_capital numeric not null default 0, start_date date not null default current_date, created_at timestamp with time zone not null default now());
CREATE TABLE public.cig_items (id uuid primary key default gen_random_uuid(), name text not null unique, quantity numeric not null default 0, wholesale_price numeric not null default 0, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
CREATE TABLE public.cig_transfers (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.cig_items(id), item_name text not null, quantity numeric not null check (quantity > 0), wholesale_price numeric not null default 0, transfer_date date not null default current_date, created_at timestamp with time zone not null default now());
CREATE INDEX cig_transfers_item_idx ON public.cig_transfers(item_id);
CREATE INDEX cig_transfers_date_idx ON public.cig_transfers(transfer_date);
CREATE TABLE public.cig_purchases (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.cig_items(id), item_name text not null, quantity numeric not null check (quantity > 0), wholesale_price numeric not null default 0, purchase_date date not null default current_date, created_at timestamp with time zone not null default now());
CREATE INDEX cig_purchases_item_idx ON public.cig_purchases(item_id);
CREATE INDEX cig_purchases_date_idx ON public.cig_purchases(purchase_date);
CREATE TABLE public.cig_settlements (id uuid primary key default gen_random_uuid(), settlement_date date not null default current_date, amount numeric not null default 0, note text, created_at timestamp with time zone not null default now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cig_settings TO authenticated, anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cig_items TO authenticated, anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cig_transfers TO authenticated, anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cig_purchases TO authenticated, anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cig_settlements TO authenticated, anon;
GRANT ALL ON public.cig_settings TO service_role;
GRANT ALL ON public.cig_items TO service_role;
GRANT ALL ON public.cig_transfers TO service_role;
GRANT ALL ON public.cig_purchases TO service_role;
GRANT ALL ON public.cig_settlements TO service_role;
ALTER TABLE public.cig_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cig_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cig_transfers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cig_purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cig_settlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "cig_settings open access" ON public.cig_settings FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "cig_items open access" ON public.cig_items FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "cig_transfers open access" ON public.cig_transfers FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "cig_purchases open access" ON public.cig_purchases FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "cig_settlements open access" ON public.cig_settlements FOR ALL USING (true) WITH CHECK (true);
CREATE TRIGGER cig_items_updated_at BEFORE UPDATE ON public.cig_items FOR EACH ROW EXECUTE FUNCTION set_updated_at();
